// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor1, address actor2) public {
        vm.assume(actor1 != actor2);
        vm.assume(actor1 != address(c) && actor2 != address(c));
        vm.assume(actor1 != address(this) && actor2 != address(this));
        vm.assume(actor1.code.length == 0 && actor2.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 4);

        // actor1 deposits and withdraws once
        vm.deal(actor1, amount);
        vm.prank(actor1);
        c.deposit{value: amount}();
        vm.prank(actor1);
        try c.withdrawAll() {} catch {}

        // any EOA may then withdraw: C releases its lock, so this succeeds;
        // the mutant never releases the lock, so this reverts.
        bool ok;
        vm.prank(actor2);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
